class WorkArea
{
public:
    void RefreshForVirtualDesktop(const GUID& virtualDesktopId);
private:
    FancyZonesDataTypes::WorkAreaId m_uniqueId; // no longer const
};

void WorkArea::RefreshForVirtualDesktop(const GUID& virtualDesktopId)
{
    if (m_uniqueId.virtualDesktopId == virtualDesktopId)
        return;

    auto previousId = m_uniqueId;
    m_uniqueId.virtualDesktopId = virtualDesktopId;
    InitLayout(previousId);
    InitSnappedWindows();
}

TEST_METHOD(RefreshForVirtualDesktop_DoesNotRequireWorkAreaRecreation)
{
    auto workArea = WorkArea::Create(m_hInst, oldId, {}, m_workAreaRect);
    auto hwnd = workArea->GetWorkAreaWindow();
    workArea->RefreshForVirtualDesktop(newId.virtualDesktopId);
    Assert::AreEqual(hwnd, workArea->GetWorkAreaWindow());
    Assert::IsTrue(workArea->UniqueId().virtualDesktopId == newId.virtualDesktopId);
}
